-- 2026-11-11  Frozen Food category, 12 new frozen products (draft), French descriptions, new address
-- Safe to run more than once: only adds what is missing and fills empty French text; never changes prices.
USE Tanjofoods;

UPDATE products SET category_id = (SELECT category_id FROM categories WHERE code = 'FROZEN') WHERE sku = 'TF-RT-001' AND category_id = (SELECT category_id FROM categories WHERE code = 'RTE');
UPDATE products SET short_desc_en = 'Rich, creamy and flavourful – just add chicken (or paneer or your choice of protein) for butter chicken at home.' WHERE sku = 'TF-SC-001' AND short_desc_en = 'Rich, creamy and flavourful – just add chicken (or paneer) for butter chicken at home.';
UPDATE products SET short_desc_fr = 'Des craquelins fins et croustillants à la farine de riz, légèrement épicés. Recette authentique du sud de l’Inde, sans gluten.' WHERE sku = 'TF-SN-001' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Des bâtonnets de murukku au beurre qui fondent dans la bouche : légers, croquants et irrésistibles.' WHERE sku = 'TF-SN-002' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Murukku classique en spirale au cumin et au sésame : un incontournable de l’heure du thé.' WHERE sku = 'TF-SN-003' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Un mélange de collations indiennes aux saveurs audacieuses, composé de sev, d''arachides, de lentilles et de feuilles de curry.' WHERE sku = 'TF-SN-004' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Des bâtonnets croustillants à la farine de gramme, relevés au poivre, avec une touche typiquement sud-indienne.' WHERE sku = 'TF-SN-005' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Des perles dorées et croquantes à la farine de riz, à la noix de coco et au sésame.' WHERE sku = 'TF-SN-006' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Pâtisserie croustillante garnie de pommes de terre épicées et de petits pois. Réchauffer et servir.' WHERE sku = 'TF-RT-001' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Une recette riche, onctueuse et savoureuse : il suffit d’y ajouter du poulet (ou du paneer, ou la protéine de votre choix) pour préparer un poulet au beurre à la maison.' WHERE sku = 'TF-SC-001' AND (short_desc_fr IS NULL OR short_desc_fr = '');
UPDATE products SET short_desc_fr = 'Boisson au yogourt indienne authentique, préparée avec de la vraie mangue. Sans arômes artificiels.' WHERE sku = 'TF-BV-001' AND (short_desc_fr IS NULL OR short_desc_fr = '');

